fn crt(r1: i64, m1: i64, r2: i64, m2: i64) -> i64 {
    let g = gcd(m1, m2);
    let lcm = m1 / g * m2;
    let mut x = r1;
    while x % m2 != r2 {
        x = x + m1;
        if x > lcm {
            return 0 - 1;
        }
    }
    x
}

